@Test
final void summaryCursorIsVersionedAndBoundToResourceFilterAndDirection() {
    try (SessionRepository repository = createRepository()) {
        repository.create("session-a1", MODEL, "workspace-a", NOW);
        repository.create("session-a2", MODEL, "workspace-a", NOW.minusSeconds(1));
        repository.create("session-b1", MODEL, "workspace-b", NOW.minusSeconds(2));
        repository.create("session-b2", MODEL, "workspace-b", NOW.minusSeconds(3));

        var filtered = repository.listSummaries(new SessionRepository.SummaryQuery(
                Optional.empty(), 1, Optional.of("workspace-a")));
        var unfiltered = repository.listSummaries(new SessionRepository.SummaryQuery(
                Optional.empty(), 1, Optional.empty()));
        String filteredCursor = filtered.nextCursor().orElseThrow();
        String unfilteredCursor = unfiltered.nextCursor().orElseThrow();

        assertAll(
                () -> assertThrows(IllegalArgumentException.class, () -> repository.listSummaries(
                        new SessionRepository.SummaryQuery(Optional.of(filteredCursor), 1,
                                Optional.of("workspace-b")))),
                () -> assertThrows(IllegalArgumentException.class, () -> repository.listSummaries(
                        new SessionRepository.SummaryQuery(Optional.of(filteredCursor), 1, Optional.empty()))),
                () -> assertThrows(IllegalArgumentException.class, () -> repository.listSummaries(
                        new SessionRepository.SummaryQuery(Optional.of(unfilteredCursor), 1,
                                Optional.of("workspace-a")))),
                () -> assertThrows(IllegalArgumentException.class, () -> repository.listSummaries(
                        new SessionRepository.SummaryQuery(Optional.of(rewriteCursor(filteredCursor,
                                raw -> raw.replace("v1", "v2"))), 1, Optional.of("workspace-a")))),
                () -> assertThrows(IllegalArgumentException.class, () -> repository.listSummaries(
                        new SessionRepository.SummaryQuery(Optional.of(rewriteCursor(filteredCursor,
                                raw -> raw.replace("session-summary", "other-resource"))), 1,
                                Optional.of("workspace-a")))),
                () -> assertThrows(IllegalArgumentException.class, () -> repository.listSummaries(
                        new SessionRepository.SummaryQuery(Optional.of(rewriteCursor(filteredCursor,
                                raw -> raw.replace("updated-at-desc-session-id-asc", "reverse"))), 1,
                                Optional.of("workspace-a")))),
                () -> assertThrows(IllegalArgumentException.class, () -> repository.listSummaries(
                        new SessionRepository.SummaryQuery(Optional.of(rewriteCursor(filteredCursor,
                                raw -> raw.substring(0, raw.lastIndexOf('\n')))), 1,
                                Optional.of("workspace-a")))));
    }
}

private static String rewriteCursor(String cursor, java.util.function.UnaryOperator<String> change) {
    String raw = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8);
    return Base64.getUrlEncoder().withoutPadding()
            .encodeToString(change.apply(raw).getBytes(StandardCharsets.UTF_8));
}

